// TH16 v1.00a Stage 3 Boss1 非符1 (st03bs.ecl.txt:60-128, 依赖 Boss1_at 130-177)
// 入口状态: Boss 在 (0,128)，moveLimit(0,128,280,64)，setHitbox(48,48)/setHurtbox(40,40)
//   (st03bs.ecl.txt:14,31-33；框半径按 enemy-state.md 普通圆形分支取半)。
// 源骨架: timerReset; setInterrupt(0, 2000/1800, 1920, "BossCard1"); wait(60);
//   loop { Boss1_at(0,4,+1deg); wait(20/10); moveRand(60,4,1.0); wait(80/60);
//          Boss1_at(1,13,-1deg); wait(20/10); moveRand(60,4,1.0); wait(80/60); }
// 秒表/血线由 phase_begin 外壳承载（源 setInterrupt 时间 1920、血线 2000/1800）。
const TIME_LIMIT: int = 2044; // 120 外壳缓冲 + 1920 源窗口 + 4 启动余量
const OPENING_BUFFER: int = 120;
const TH16_RICE: int = 480; // 源 etSprite 8 -> bullet-types.md type 8

const SPAWN_X: fx = 0fx;
const SPAWN_Y: fx = 128fx;

// 源 moveLimit(0,128,280,64) 后两参是完整宽高：
// 实际位置 x∈[-140,140]、y∈[96,160]；moveRand 方向内区为中心±宽高/4（movement.md）。
const CLAMP_X: fx = 140fx;
const CLAMP_Y_MIN: fx = 96fx;
const CLAMP_Y_MAX: fx = 160fx;
const DIR_X: fx = 70fx;
const DIR_Y_MIN: fx = 112fx;
const DIR_Y_MAX: fx = 144fx;

// 每颗弹的 TH16 EX 链（Boss1_at 148-161）：
//   ANIM type2 a=1       -> 出生退位移 -4*velocity = -6px（净出生距离 etDist 64-6=58）
//   SAVE type 0x800000    -> 记录出生角（第二段段界读回）
//   OFFSCREEN 0x100 a=160 -> offscreen_keep(160)
//   STEP 0x10 a=60 b=1 c=1 d=0 r=0 s=2.0  -> 60帧减速1.5->0，段界朝自机、速度2.0
//   STEP 0x10 a=120 b=1 c=3 d=2 r=9999999 s=1.0/1.0/2.0/2.5
//                        -> 120帧减速2.0->0，段界取存档出生角、速度按难度
// 源 STEP 的“逻辑标量”在这条链上没有后续读取，可直接用 step_speed 的线性衰减。
xformdef BOSS1_BULLET(return_speed: fx) {
    offscreen_keep(160);
    @60 step_speed(0fx, 60);
    set_speed(2fx);
    set_angle(at_effect(aim_player()));
    @120 step_speed(0fx, 120);
    set_speed(return_speed);
    set_angle(at_spawn($self_angle));
}

// moveRand(60,4,1.0) 目标配方（movement.md，限位宽度换成本卡 280）。
// 敌槽用途：int0 = 下一步计数；fx0/fx1 = 本次调用的单位方向向量。
sub mb_arm_next() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var spd: fx = 0fx;
    if k < 60 { spd = ((60 - k) as fx) / 60; }
    var nx: fx = $self_x + self_fx(0) * spd;
    var ny: fx = $self_y + self_fx(1) * spd;
    if nx < -CLAMP_X { nx = -CLAMP_X; }
    if nx > CLAMP_X { nx = CLAMP_X; }
    if ny < CLAMP_Y_MIN { ny = CLAMP_Y_MIN; }
    if ny > CLAMP_Y_MAX { ny = CLAMP_Y_MAX; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub mb_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mb_arm_next();
}
sub mb_rand() {
    // 源 412：R = pi * signed-unit-random，按当时 FINAL 位置与玩家 x 选方向。
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -DIR_X {
        a = r / 3;
    } else {
        if $self_x > DIR_X {
            a = r / 3 + 32768;
            if a > 32768 { a = a - 65536; } // 源该分支显式归一
        } else {
            a = r / 4;
            var pick: int = rand(65536) % 3;
            if $player_x > $self_x {
                if pick == 0 { a = a + 32768; }
            } else {
                if pick != 0 { a = a + 32768; }
            }
        }
    }
    if $self_y < DIR_Y_MIN {
        if a < 0 { a = -a; }
    } else {
        if $self_y > DIR_Y_MAX {
            if a < 0 { a = -a; }
            a = -a;
        }
    }
    // 原生 ±pi/2 护栏（0.05rad，最近 BAM 边界），本卡方向区间内不可达，按配方保留。
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else {
        if a > 15862 && a < 16906 {
            if a < 16384 { a = 15862; } else { a = 16906; }
        }
    }
    mb_begin(a as angle);
}
// 源每帧“移动/限位 -> ECL -> 体碰”；目标阶段5在ECL后积分，
// 因此每次 wait 前后预排下一次源运动位移（配方见 movement.md）。
sub mb_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mb_arm_next();
    }
}

// Boss1_at(A,B,C): 8 波，每波间隔10帧，基准角每波转 C（Lunatic/Hard 额外再加 2C）。
// 源 etAim 3 = 定方向整周环，etCount N×1，etSpeed 1.5/1.0（单层取1.5），etDist 64。
sub boss1_at(color: int, step: angle, count: int, ret: fx, gap: int) {
    sh_reset(0);
    sh_sprite(0, TH16_RICE, color);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, count, 1);
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, 58fx);
    sh_xform(0, BOSS1_BULLET(ret));
    var d: angle = 90deg;
    for i in 0..8 {
        sh_angle(0, d, 0deg);
        sh_fire(0);
        d = d + step;
        wait(10);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);

    var rank: int = global(GVAR_RANK);
    var count: int = 10;
    var step: angle = 1deg;
    var gap: int = 20;
    var after: int = 80;
    var ret: fx = 1fx;
    if rank == 1 { count = 20; }
    if rank == 2 {
        count = 26;
        step = 3deg;
        ret = 2fx;
    }
    if rank == 3 {
        count = 30;
        step = 3deg;
        gap = 10;
        after = 60;
        ret = 2.5fx;
    }

    wait(60); // 源 Boss1 的 wait(60) 后才进入攻击循环
    loop {
        boss1_at(4, step, count, ret, gap);
        wait(gap);
        mb_rand();
        mb_wait(after);
        boss1_at(13, 0deg - step, count, ret, gap);
        wait(gap);
        mb_rand();
        mb_wait(after);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var hp: int = 14000; // 源 Boss 入口 lifeSet 14000/13800
    if global(GVAR_RANK) >= RANK_HARD { hp = 13800; }
    _ = spawn_enemy(SPAWN_X, SPAWN_Y, hp, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    var thresh: int = 2000; // 源 setInterrupt 血线 2000/1800
    if global(GVAR_RANK) >= RANK_HARD { thresh = 1800; }
    phase_begin(0, pattern, TIME_LIMIT, thresh);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 14000, 0, 0, 0, control);
    loop { wait(600); }
}
